'use client';

import { IconChevronLeft, IconChevronRight, IconDots } from '@tabler/icons-react';
import { useMemo, type HTMLAttributes, type JSX } from 'react';
import { Button as RACButton, useLocale } from 'react-aria-components';
import styles from './pagination.module.css';

const cx = (...c: Array<string | false | null | undefined>) => c.filter(Boolean).join(' ');

type PageItem = number | 'start-ellipsis' | 'end-ellipsis';

const range = (start: number, end: number): number[] =>
  Array.from({ length: Math.max(end - start + 1, 0) }, (_, i) => start + i);

/**
 * Pages to show: boundary pages at each end, siblings around the current page, ellipses for the gaps.
 * With enough pages the item count is constant (2 × boundary + 2 × siblings + 3), so the control never changes width.
 */
function getPageItems(page: number, pageCount: number, siblingCount: number, boundaryCount: number): PageItem[] {
  const startPages = range(1, Math.min(boundaryCount, pageCount));
  const endPages = range(Math.max(pageCount - boundaryCount + 1, boundaryCount + 1), pageCount);
  const siblingsStart = Math.max(
    Math.min(page - siblingCount, pageCount - boundaryCount - siblingCount * 2 - 1),
    boundaryCount + 2,
  );
  const siblingsEnd = Math.min(
    Math.max(page + siblingCount, boundaryCount + siblingCount * 2 + 2),
    endPages.length > 0 ? (endPages[0] as number) - 2 : pageCount - 1,
  );
  const items: PageItem[] = [...startPages];
  if (siblingsStart > boundaryCount + 2) items.push('start-ellipsis');
  else if (boundaryCount + 1 < pageCount - boundaryCount) items.push(boundaryCount + 1);
  items.push(...range(siblingsStart, siblingsEnd));
  if (siblingsEnd < pageCount - boundaryCount - 1) items.push('end-ellipsis');
  else if (pageCount - boundaryCount > boundaryCount) items.push(pageCount - boundaryCount);
  items.push(...endPages);
  return items;
}

export interface PaginationProps extends Omit<HTMLAttributes<HTMLElement>, 'children' | 'onChange'> {
  /** Current page, 1-based. */
  page: number;
  /** Total number of pages. */
  pageCount: number;
  onPageChange?: (page: number) => void;
  /** Pages shown on each side of the current page. */
  siblingCount?: number;
  /** Pages always shown at the start and end. */
  boundaryCount?: number;
  /** `default` shows page buttons; `compact` shows "Page 3 of 12" between previous and next. */
  variant?: 'default' | 'compact';
  /**
   * Accessible name. Landmarks must be unique on a page, so when a page has more than one pagination
   * (or other navigation), name each for what it pages: "Search results pages", "Orders pages".
   */
  label?: string;
  /**
   * Render as a navigation landmark (`<nav>`). Set false for paging that belongs to a component rather than the
   * page (DataTablePagination does), which renders a labelled group instead and never collides with other landmarks.
   */
  landmark?: boolean;
  /** Text of the previous button; also its accessible name when the text is visually hidden. */
  previousLabel?: string;
  /** Text of the next button; also its accessible name when the text is visually hidden. */
  nextLabel?: string;
  /** Word used in "Page 3 of 12" and in each page button's accessible name ("Page 3"). */
  pageLabel?: string;
  /** Word used in "Page 3 of 12". */
  ofLabel?: string;
  isDisabled?: boolean;
}

/**
 * Page navigation. Previous/next labels hide below a 520px container; below 400px the page buttons collapse
 * into "Page 3 of 12". At the first and last page, previous/next stay focusable but are marked `aria-disabled`,
 * so keyboard focus is never dropped.
 */
export function Pagination({
  page,
  pageCount,
  onPageChange,
  siblingCount = 1,
  boundaryCount = 1,
  variant = 'default',
  label = 'Pagination',
  previousLabel = 'Previous',
  nextLabel = 'Next',
  pageLabel = 'Page',
  ofLabel = 'of',
  isDisabled = false,
  landmark = true,
  className,
  ...rest
}: PaginationProps): JSX.Element {
  const { locale } = useLocale();
  const nf = useMemo(() => new Intl.NumberFormat(locale), [locale]);
  const Root = landmark ? 'nav' : 'div';
  const count = Math.max(0, Math.floor(pageCount));
  const current = Math.min(Math.max(1, Math.floor(page)), Math.max(1, count));
  const items = variant === 'compact' ? [] : getPageItems(current, count, Math.max(0, siblingCount), Math.max(1, boundaryCount));
  const atStart = current <= 1;
  const atEnd = current >= count;

  const go = (next: number) => {
    if (isDisabled || next < 1 || next > count || next === current) return;
    onPageChange?.(next);
  };

  const summary = (
    <span className={styles.summaryText}>
      {pageLabel} <span className={styles.num}>{nf.format(count === 0 ? 0 : current)}</span> {ofLabel}{' '}
      <span className={styles.num}>{nf.format(count)}</span>
    </span>
  );

  return (
    <Root {...rest} role={landmark ? undefined : 'group'} aria-label={label} data-variant={variant} className={cx(styles.root, className)}>
      <ul className={styles.list}>
        <li className={styles.stepItem}>
          <RACButton
            className={cx(styles.button, styles.step)}
            aria-disabled={atStart || undefined}
            isDisabled={isDisabled}
            onPress={() => !atStart && go(current - 1)}
          >
            <IconChevronLeft className={styles.dirIcon} aria-hidden="true" size="1.15em" stroke={1.75} />
            <span className={styles.stepLabel}>{previousLabel}</span>
          </RACButton>
        </li>

        {items.map((item) =>
          typeof item === 'number' ? (
            <li key={item} className={styles.pageItem}>
              <RACButton
                className={cx(styles.button, styles.page)}
                aria-label={`${pageLabel} ${nf.format(item)}`}
                aria-current={item === current ? 'page' : undefined}
                isDisabled={isDisabled}
                onPress={() => go(item)}
              >
                {nf.format(item)}
              </RACButton>
            </li>
          ) : (
            <li key={item} className={cx(styles.pageItem, styles.ellipsis)} aria-hidden="true">
              <IconDots size="1em" stroke={1.75} />
            </li>
          ),
        )}

        <li className={cx(styles.summary, variant === 'compact' && styles.summaryCompact)} aria-live={variant === 'compact' ? 'polite' : undefined}>
          {summary}
        </li>

        <li className={styles.stepItem}>
          <RACButton
            className={cx(styles.button, styles.step)}
            aria-disabled={atEnd || undefined}
            isDisabled={isDisabled}
            onPress={() => !atEnd && go(current + 1)}
          >
            <span className={styles.stepLabel}>{nextLabel}</span>
            <IconChevronRight className={styles.dirIcon} aria-hidden="true" size="1.15em" stroke={1.75} />
          </RACButton>
        </li>
      </ul>
    </Root>
  );
}

/*
 * Pagination. Page buttons mirror Button's ghost style; the current page mirrors Button outline.
 * Responds to its own width (container query), never the viewport.
 */

.root {
  box-sizing: border-box;
  container: strata-pagination / inline-size;
  display: flex;
  justify-content: center;
  inline-size: 100%;
  min-inline-size: 0;
}

.list {
  display: flex;
  align-items: center;
  gap: var(--strata-space-1);
  margin: 0;
  padding: 0;
  list-style: none;
}

.pageItem,
.stepItem {
  display: flex;
}

.num {
  font-variant-numeric: tabular-nums;
}

/* ------------------------------------------------------------------ *
 * Buttons
 * ------------------------------------------------------------------ */

.button {
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--strata-space-1);
  min-block-size: var(--strata-control-height);
  min-inline-size: var(--strata-control-height);
  margin: 0;
  padding-block: 0;
  padding-inline: var(--strata-space-2);
  border: 1px solid transparent;
  border-radius: var(--strata-radius-button);
  background-color: transparent;
  color: var(--strata-color-text-default);
  font-family: inherit;
  font-size: var(--strata-font-size-md);
  font-variant-numeric: tabular-nums;
  font-weight: var(--strata-font-weight-medium);
  line-height: var(--strata-line-height-tight);
  letter-spacing: inherit;
  white-space: nowrap;
  cursor: pointer;
  user-select: none;
  outline: none;
  -webkit-tap-highlight-color: transparent;
}

.button[data-hovered] {
  background-color: color-mix(in oklab, var(--strata-color-text-default) 6%, transparent);
}

.button[data-pressed] {
  background-color: color-mix(in oklab, var(--strata-color-text-default) 10%, transparent);
}

.button[data-focus-visible] {
  outline: 2px solid var(--strata-color-focus-ring);
  outline-offset: 2px;
}

.page[aria-current='page'] {
  border-color: var(--strata-color-border-strong);
  background-color: var(--strata-color-surface-default);
  cursor: default;
}

.page[aria-current='page'][data-hovered] {
  background-color: color-mix(in oklab, var(--strata-color-text-default) 6%, var(--strata-color-surface-default));
}

.step {
  padding-inline: var(--strata-space-2) var(--strata-space-3);
}

.stepItem:last-child .step {
  padding-inline: var(--strata-space-3) var(--strata-space-2);
}

/* Boundary: still focusable (focus is never dropped), announced as disabled, drawn as disabled. */
.step[aria-disabled='true'],
.button[data-disabled] {
  background-color: transparent;
  color: var(--strata-color-text-disabled);
  cursor: default;
}

.page[data-disabled][aria-current='page'] {
  border-color: var(--strata-color-border-default);
}

.dirIcon {
  flex: none;
}

.dirIcon:dir(rtl) {
  scale: -1 1;
}

.ellipsis {
  align-items: center;
  justify-content: center;
  min-inline-size: var(--strata-control-height);
  min-block-size: var(--strata-control-height);
  color: var(--strata-color-text-subtle);
  font-size: var(--strata-font-size-md);
  user-select: none;
}

@media (prefers-reduced-motion: no-preference) {
  .button {
    transition-property: background-color, border-color, color;
    transition-duration: var(--strata-motion-duration-fast);
    transition-timing-function: var(--strata-motion-easing);
  }
}

/* ------------------------------------------------------------------ *
 * Summary ("Page 3 of 12") — the compact variant, and the default variant's narrow fallback
 * ------------------------------------------------------------------ */

.summary {
  display: none;
  align-items: center;
  padding-inline: var(--strata-space-2);
  color: var(--strata-color-text-subtle);
  font-size: var(--strata-font-size-sm);
  white-space: nowrap;
}

.summary .num {
  color: var(--strata-color-text-default);
  font-weight: var(--strata-font-weight-medium);
}

.summaryCompact {
  display: flex;
}

/* Compact: previous/next are icon-only; the text stays as the accessible name. */
.root[data-variant='compact'] .step {
  padding-inline: var(--strata-space-2);
}

.root[data-variant='compact'] .stepLabel {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

@container strata-pagination (inline-size < 520px) {
  .step,
  .stepItem:last-child .step {
    padding-inline: var(--strata-space-2);
  }

  .stepLabel {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }
}

@container strata-pagination (inline-size < 400px) {
  .pageItem {
    display: none;
  }

  .summary {
    display: flex;
  }
}
